/* @lc app=leetcode id=3326 lang=kotlin */ class Solution { fun spf(x: Int): Int = (2..Math.sqrt(x.toDouble()).toInt()).firstOrNull { x % it == 0 } ?: x fun minOperations(nums: IntArray): Int = nums.reversed().fold(Int.MAX_VALUE to 0) { (nxt, ops), x -> if (ops < 0) nxt to ops else if (x <= nxt) x to ops else spf(x).let { s -> if (s <= nxt) s to ops + 1 else nxt to -1 } }.second }